"""
This file contains the objects for taking in pytmc-parsed TMC files and
generating Python-level configuration information.
"""
import copy
import itertools
import logging
import math
import re

from . import parser
from .record import RecordPackage, StPositionStateRecordPackage

# from collections.abc import Generator
# from typing import Union


logger = logging.getLogger(__name__)


# Break configuration str into list of lines paired w/ their delimiters
_LINE_FINDER = re.compile(r"(?P<line>.+?)(?P<delim>(?:[;\n\r]+|$))")
_LINE_PARSER = re.compile(r"(?P<title>[\S]+):(?:[^\S]*)(?P<tag>.*)")
_FIELD_FINDER = re.compile(r"(?P<f_name>[\S]+)(?:[^\S]*)(?P<f_set>.*)")

# Valid options for 'io' in pragma:
IO_OUTPUT = ("output", "io", "o", "rw")
IO_INPUT = ("input", "i", "ro")
KNOWN_BAD_TYPES = ("ALIAS", "DATE", "DATE_AND_TIME", "DT", "TIME", "TIME_OF_DAY", "TOD")

_UPDATE_RE = re.compile(
    # Rate portion (e.g., 1 s, 1s, 1Hz, 1 Hz)
    r"^(?P<rate>\d*\.\d+|\d+)\s*(?P<hz_or_sec>hz|s)"
    # Poll or notify (or default)
    r"(\s+(?P<method>poll|notify))?$",
    flags=re.IGNORECASE,
)

UPDATE_RATE_DEFAULT = {"frequency": 1, "seconds": 1, "method": "poll"}
VALID_POLL_RATES_HZ = (
    1.0 / 50,  # 0.02Hz - 1 update every 50 seconds
    1.0 / 10,  # 0.1 Hz - 1 update every 10 seconds
    1.0 / 2,  # 0.5 Hz - 1 update every 2 seconds
    1,  # 1.0 Hz - 1 update every 1 second (default)
    2,
)  # 2.0 Hz - 2 updates every 1 second


_ARCHIVE_RE = re.compile(
    # Rate portion (e.g., 1 s, 1s, 1Hz, 1 Hz)
    r"^(?P<rate>\d*\.\d+|\d+)\s*(?P<hz_or_sec>hz|s)"
    # Poll or notify (or default)
    r"(\s+(?P<method>scan|monitor))?$",
    flags=re.IGNORECASE,
)
ARCHIVE_DEFAULT = {"frequency": 1, "seconds": 1, "method": "scan"}

# Special, reserved keys:
SUBITEM = "_subitem_"
PRAGMA = "_pragma_"

# Data type of a device state table: ARRAY[motors] OF ARRAY[states] OF this
STATE_TABLE_TYPE = "ST_PositionState"
DISALLOWED_SUBITEMS = {"pv", SUBITEM, PRAGMA, "field", "link"}

# Default for array index expansion:
EXPAND_DEFAULT = ":%.2d"


def split_pytmc_pragma(pragma_text):
    """
    Return dictionaries for each line.
    Derived from raw_config

    Parameters
    ----------
    raw_config : str
        completely unformatted string from configuration. Defaults to
        raw_config.

    Returns
    -------
    list
        This list contains a dictionary for each line broken up into two
        keys: 'title' and 'tag'.
    """
    conf_lines = [m.groupdict()["line"] for m in _LINE_FINDER.finditer(pragma_text)]

    # create list of lines information only. Strip out delimiters, empty lines
    result_no_delims = [
        _LINE_PARSER.search(line) for line in conf_lines if line.strip()
    ]

    # Break lines into list of dictionaries w/ title/tag structure
    if None in result_no_delims:
        invalid_lines = "\n".join(
            f"--> | {line}" if _LINE_PARSER.search(line) is None else f"    | {line}"
            for line in conf_lines
        )
        raise ValueError(f"Found invalid pragma line(s):\n{invalid_lines}")

    def line_to_dict(match):
        """
        Strip out extra whitespace in the tag and/or split out fields into
        {'f_name': '...', 'f_set': '...'}
        """
        groupdict = match.groupdict()
        tag = groupdict["tag"]
        groupdict["tag"] = (
            split_field(tag.strip()) if groupdict["title"] == "field" else tag.strip()
        )
        return groupdict

    return [line_to_dict(m) for m in result_no_delims]


def split_field(string):
    """
    When applied to field line's tag, break the string into its own dict

    Parameters
    ----------
    string : str
        This is the string to be broken into field name and field setting

    Returns
    -------
    dict
        Keys are 'f_name' for the field name and 'f_set' for the corresponding
        setting.
    """
    return _FIELD_FINDER.search(string).groupdict()


def separate_configs_by_pv(config_lines):
    """
    Take in a pre-parsed pragma and yield ``(pvname, config_lines)`` pairs,
    one per ``pv:`` entry found.

    Example input::

        [{'title': 'pv', 'tag': 'a'},
         {'title': 'io', 'tag': 'io_for_a'},
         {'title': 'pv', 'tag': 'b'},
         {'title': 'io', 'tag': 'io_for_b'},
         ]

    Yields::

        ('a', [{'title': 'pv', ...}, {'title': 'io', ...}])
        ('b', [{'title': 'pv', ...}, {'title': 'io', ...}])

    Pragma keys that appear 'before' the first ``pv:`` line (such as
    ``alias:``) are buffered and prepended to the first pv block, so that
    pragmas like::

        alias: TST:M1.LLS
        pv: TST:M1:btestLLS
        io: i

    are handled correctly and the alias is not silently dropped.
    """
    pv, config = None, None
    pre_pv_lines = []

    for line in config_lines:
        if line["title"] == "pv":
            if config is not None:
                yield pv, config

            pv = line["tag"]
            # Flush any pragma lines that preceded the first pv: line
            # (e.g. alias: declared before pv:) into this config block.
            config = list(pre_pv_lines)
            pre_pv_lines = []

        if config is not None:
            config.append(line)
        else:
            # No pv: seen yet: buffer this line so it can be attached to
            # the next pv: block that follows.
            pre_pv_lines.append(line)

    if config is not None:
        yield pv, config


def index_digits(upper_bound):
    """
    Width of the zero-padded numeric PV suffix for an array dimension.

    One more digit than the declared upper bound needs (bounds up to 9 are
    padded to 2 digits, 10 through 99 to 3). The width comes from the
    declared bound, not from the elements selected by the ``array:`` pragma;
    existing IOCs depend on the resulting PV names.
    """
    return math.floor(math.log10(upper_bound)) + 2


def get_array_suffix(config, array_index, *, default=EXPAND_DEFAULT):
    """
    Return array index suffix based on the expand settings in the config.
    """
    return config.get("expand", default) % array_index


def parse_expand_names(names_setting, dimensions, *, expected_count=None):
    """
    Parse an 'expand-names' specifier in a pragma into a list of per-element
    PV suffix names.

    The pragma value is a comma-separated list of names whose length must
    match the number of elements in the array dimension. The names replace
    the default numeric index suffix produced by ``get_array_suffix``, so
    that role-based PV names like ``MMS``, ``CLZ``, ``CLF`` can be used in
    place of ``01``, ``02``, ``03`` for grouped device arrays.

    Parameters
    ----------
    names_setting : str
        The raw value of the ``expand-names`` pragma key (e.g.
        ``"MMS, CLZ, CLF, YAG"``).

    dimensions : 2-tuple
        Lower and upper bound (inclusive) of the array corresponding to the
        pragma. Used to derive the expected name count when
        ``expected_count`` is not provided.

    expected_count : int, optional
        Override the count derived from ``dimensions``. When the pragma also
        carries an ``array:`` slice (e.g. ``array: 1..3`` on a
        ``[1..MAX]``-bounded array), the caller passes the slice size here
        so that ``expand-names`` is validated against the number of
        elements actually emitted rather than the declared bounds.

    Returns
    -------
    list of str
        One name per array element, in declaration order.

    Raises
    ------
    ValueError
        If the comma-separated name count does not match the expected
        count, or if the dimensions argument is invalid.
    """
    try:
        low, high = dimensions
    except Exception:
        raise ValueError(
            f"Invalid dimensions {dimensions!r} for expand-names specifier "
            f"{names_setting!r}"
        )

    names = [n.strip() for n in names_setting.split(",") if n.strip()]
    if expected_count is not None:
        expected = expected_count
        target_label = "the array: slice"
    else:
        expected = high - low + 1
        target_label = f"array bounds [{low}..{high}]"
    if len(names) != expected:
        raise ValueError(
            f"expand-names has {len(names)} entries but {target_label} "
            f"require {expected}"
        )
    return names


def dictify_config(raw_conf, array_index=None):
    """
    Make a raw config list into an easier-to-use dictionary

    Example::
        [{'title': 'pv', 'tag': 'a'},
         {'title': 'io', 'tag': 'io_for_a'},
         {'title': 'field', 'tag': {'f_name': 'fieldname', 'f_set': 'value'}},
         ]

    Becomes::

        {'pv': 'a',
         'io': 'io_for_a',
         'field': {'fieldname': 'value'}}
    """

    title_tag_pairs = [(item["title"], item["tag"]) for item in raw_conf]

    fields = {
        tag["f_name"]: tag["f_set"]
        for title, tag in title_tag_pairs
        if title == "field"
    }

    config = {
        title: tag
        for title, tag in title_tag_pairs
        if "." not in title  # Handle subitem entries specially
    }

    if fields:
        config["field"] = fields

    if array_index is not None:
        config["pv"] += get_array_suffix(config, array_index)

    def add_subitem(d, key, value):
        """Add a subitem `key: value` to dictionary `d`."""
        if "." in key:
            # The first a.b.c.pragma indicate the sub-(sub-) item for 'pragma':
            child, remainder = key.split(".", 1)
            if child not in d:
                d[child] = {PRAGMA: []}
            return add_subitem(d[child], remainder, value)

        if key in DISALLOWED_SUBITEMS:
            raise ValueError(f"Unsupported pragma key in subitem: {key}")
        # The final key is a pytmc-supported pragma:
        d[PRAGMA].append((key, value))

    for title, tag in title_tag_pairs:
        if "." in title:
            if SUBITEM not in config:
                config[SUBITEM] = {}
            add_subitem(config[SUBITEM], title, tag)

    return config


def _merge_subitems(target: dict, source: dict):
    """
    In-place merge `source` into `target`.

    Sub-item dictionaries, held at the top-level key ``_subitem_``, are nested
    dictionaries containing sub-item names or the special key ``_pragma_``,
    which can modify the pragma at the given level.

    For example::

        {'_subitem_': {'member1': {'_pragma_': [('key', '1')], ... }}}

    This top-level _subitem_ pragma dictionary contains a pragma ``key: 1``
    for the ".member1" member.  ``member1``, if structured, may also have
    keys in its dictionary named after its members.
    """
    if PRAGMA not in target:
        target[PRAGMA] = []

    for key, value in source.items():
        if key == PRAGMA:
            target[PRAGMA].extend(value)
        else:
            if key not in target:
                target[key] = {}
            _merge_subitems(target[key], value)


def _expand_configurations_from_chain(
    chain, *, pragma: str = "pytmc", allow_no_pragma=False
):
    """
    Wrapped by ``expand_configurations_from_chain``, usable for callers that
    don't want the full product of all configurations.
    """

    def handle_scalar(item, pvname, config):
        """Handler for scalar simple or structured items."""
        yield item, config

    def handle_array_complex(item, pvname, config):
        """
        Handler for arrays of structured items (or enums).

        Each selected array index produces an ``_ArrayItemProxy`` paired with
        a per-element configuration. Multi-dimensional arrays
        (``ARRAY[..] OF ARRAY[..] OF X``) are unrolled with one
        ``_ArrayItemProxy`` per leaf element; the proxy's name picks up
        an index per dimension (e.g. ``Main.astPositionState[2][5]``).

        The PV suffix appended to ``config['pv']`` is determined as follows,
        in priority order, and applied **per dimension**:

        1. ``expand-names`` is set in the pragma: applies to the **outer**
           dimension only. The ``i``-th entry in the comma-separated list
           is appended as ``":<name>"`` for the outer index. The list
           length must equal the number of elements in the outermost array
           bound; this is validated by ``parse_expand_names`` and a
           mismatch raises ``ValueError``. Inner dimensions fall through
           to numeric formatting. This form is intended for grouped device
           arrays where each element of the outer dimension has a distinct
           role (e.g. ``MMS, CLZ, CLF, YAG``) rather than a meaningful numeric position.

        2. ``expand`` is set in the pragma: applies to the **outer**
           dimension only and is treated as a printf-style format string
           applied to the numeric index, via ``get_array_suffix``. Inner
           dimensions still use the numeric default.

        3. Neither is set, or for any inner dimension: a numeric default
           of ``":%.{digits}d"`` is used, where ``digits`` is wide enough
           to format the upper bound of that dimension.

        ``axis-link`` on a 1D array of FBs accepts two forms, distinguished
        by whether the value contains a comma:

        * **Explicit list** (contains a comma): comma-separated list of
          axis references, one per array element, in declaration order
          (e.g. ``axis-link: GVL_Axes.Axes[5], GVL_Axes.Axes[6], ...``).
          The list length must equal the outer array bound. This is the
          form to use when the GVL axis array is shared across multiple
          devices and individual devices reference a non-1-based slice
          (the common case in PLC projects with one global axis pool).

        * **Implicit ``%d`` substitution** (no comma, must contain ``%``)
          — the value is treated as a printf-style format string and the
          absolute array index is substituted into it for each element
          (e.g. ``axis-link: GVL_Axes.Axes[%d]`` produces
          ``GVL_Axes.Axes[1]``, ``GVL_Axes.Axes[2]``, ... for a 1-based
          array). Use this only when the GVL slice happens to align 1:1
          with the array bounds.

        In either case the resolved per-element value is stored on the
        proxy as ``axis_link_override`` so that
        ``Symbol_FB_MotionStage.get_axis_link`` returns it instead of
        re-reading the raw pragma. A bare literal value (no comma, no
        ``%``) on an array is rejected as a programmer error: silently
        applying a single literal axis link to every element of an
        array would silently wire every motor to the same NC axis,
        which is almost always a bug.

        ``axis-link`` is not supported on multi-dimensional arrays.
        Motion FBs are always declared as 1D arrays of motors in
        practice; a 2D ``axis-link`` request is rejected so the user is
        nudged to flatten the declaration.

        The ``array:`` selector accepts an optional per-dimension form for
        multi-dimensional arrays, with ``|`` as the dimension separator
        (``;`` cannot be used because pytmc pragmas treat it as a line
        delimiter)::

            astPositionState.array: 1..4 | 1..3

        Each ``|``-separated segment is parsed with ``parse_array_settings``
        against the corresponding dimension's bounds (outer first). A
        single segment (no ``|``) retains the legacy outer-only behavior
        and inner dimensions iterate their full bounds. Trailing
        dimensions left unspecified also iterate fully. Supplying more
        segments than the array has dimensions raises ``ValueError``.
        """
        array_element_pragma = config.get("array", "")

        # All array dimensions, outer-to-inner. For 1D arrays this is a
        # single-element list; for 2D arrays it is two entries.
        dimensions = getattr(item, "array_dimensions", None)
        if not dimensions:
            # Fall back to the legacy single-dimension path for items
            # whose proxies (mocks, fakes) don't expose array_dimensions.
            dimensions = [item.array_info.bounds]

        # Split the `array:` value into per-dimension selectors on `|`.
        # A bare value (no `|`) keeps the legacy outer-only behavior;
        # trailing dimensions left unspecified default to "" (full bounds).
        # Note: `;` cannot be used as a separator because pytmc pragma
        # parsing treats it as a line delimiter.
        per_dim_selectors = [s.strip() for s in array_element_pragma.split("|")]
        if len(per_dim_selectors) > len(dimensions):
            raise ValueError(
                f"array selector {array_element_pragma!r} has "
                f"{len(per_dim_selectors)} dimensions but {item.name!r} "
                f"has {len(dimensions)}"
            )

        # Resolve outer-dimension expand-names once, before iterating.
        # expand-names applies only to the outermost dimension so that
        # role-based names override the default formatting for the
        # mechanical-role index; inner dimensions stay numeric.
        outer_low, outer_high = dimensions[0]

        # Materialize the outer-dimension selection so that
        # expand-names and axis-link explicit lists can be validated
        # against the slice size (when array: subsets the outer dim)
        # rather than the declared bounds. When no outer selector is
        # given, this is equivalent to range(outer_low, outer_high+1),
        # so existing pragmas (no array: key) keep their behavior.
        outer_selector = per_dim_selectors[0]
        outer_selected_indices = list(
            parse_array_settings(outer_selector, (outer_low, outer_high))
        )
        # Map absolute idx -> position-in-selection. Used to index into
        # names/axis_link_explicit so non-contiguous slices
        # (array: 1,3,5) also work.
        outer_position = {
            idx: pos for pos, idx in enumerate(outer_selected_indices)
        }
        outer_slice_count = len(outer_selected_indices)
        # Only pass expected_count to validators when an actual subset
        # was requested; an empty outer_selector preserves the legacy
        # bounds-based error message for unrelated mismatches.
        expected_for_validation = (
            outer_slice_count if outer_selector else None
        )

        # Resolve the selected indices of every dimension; the selection
        # sizes feed the metadata PVs (see StPositionStateRecordPackage).
        dim_selected = [
            list(
                parse_array_settings(
                    per_dim_selectors[depth] if depth < len(per_dim_selectors) else "",
                    dim_bounds,
                )
            )
            for depth, dim_bounds in enumerate(dimensions)
        ]

        names_setting = config.get("expand-names")
        if names_setting is not None:
            names = parse_expand_names(
                names_setting,
                (outer_low, outer_high),
                expected_count=expected_for_validation,
            )
        else:
            names = None

        # A device state table (2D array of ST_PositionState) is described to
        # clients through metadata records built from the array: slice and
        # expand-names. Note what is there and what is missing; whether that
        # is an error depends on the motion library (see
        # record_packages_from_symbol).
        array_metadata = None
        if len(dimensions) == 2 and item.data_type.name == STATE_TABLE_TYPE:
            missing = [
                key for key in ("array", "expand-names") if not config.get(key)
            ]
            array_metadata = {
                "pv": config["pv"],
                "macro_character": config.get("macro_character", "@"),
                "missing": missing,
            }
            if not missing:
                array_metadata.update(
                    names=list(names),
                    state_count=len(dim_selected[1]),
                    state_index_digits=index_digits(dimensions[1][1]),
                )

        # Resolve axis-link once, before iterating selected indices. Two
        # accepted forms (see method docstring): an explicit comma-
        # separated list (one entry per outer element), or a printf-
        # style template with a '%' placeholder substituted with the
        # absolute array index. axis_link_explicit holds the parsed
        # explicit list when that form is used, else None; otherwise
        # axis_link_template holds the format string.
        axis_link_setting = config.get("axis-link")
        axis_link_explicit = None
        axis_link_template = None
        if axis_link_setting is not None:
            if len(dimensions) > 1:
                raise ValueError(
                    f"axis-link is not supported on multi-dimensional arrays "
                    f"({item.name!r} has {len(dimensions)} dimensions). "
                    f"Motion FBs should be declared as 1D arrays."
                )
            # Comma is the disambiguator: TwinCAT identifiers cannot
            # contain commas, so a comma in the value means an explicit
            # list. The implicit-index form ('%d') is used only when no
            # comma is present.
            if "," in axis_link_setting:
                axis_link_explicit = [
                    entry.strip()
                    for entry in axis_link_setting.split(",")
                    if entry.strip()
                ]
                if outer_selector:
                    # When array: subsets the outer dim, axis-link
                    # entries are validated against the slice size and
                    # consumed positionally (entry N maps to the N-th
                    # selected index).
                    if len(axis_link_explicit) != outer_slice_count:
                        raise ValueError(
                            f"axis-link has {len(axis_link_explicit)} entries "
                            f"but the array: slice requires "
                            f"{outer_slice_count}"
                        )
                else:
                    expected = outer_high - outer_low + 1
                    if len(axis_link_explicit) != expected:
                        raise ValueError(
                            f"axis-link has {len(axis_link_explicit)} entries "
                            f"but array bounds [{outer_low}..{outer_high}] "
                            f"require {expected}"
                        )
            elif "%" in axis_link_setting:
                axis_link_template = axis_link_setting
            else:
                raise ValueError(
                    f"axis-link {axis_link_setting!r} on array "
                    f"{item.name!r} has no '%d' placeholder and is not a "
                    f"comma-separated list. Array elements need per-element "
                    f"axis links — use either "
                    f"'axis-link: GVL_Axes.Axes[%d]' for 1:1-aligned axes, "
                    f"or 'axis-link: GVL_Axes.Axes[5], GVL_Axes.Axes[6], ...' "
                    f"for an explicit per-element list."
                )

        def expand(remaining_dims, indices_so_far, pv_so_far):
            """Recurse over remaining dimensions, yielding one proxy per leaf."""
            if not remaining_dims:
                # Leaf: build a per-element config and proxy.
                idx_config = copy.copy(config)
                idx_config["pv"] = pv_so_far

                proxy = parser._ArrayItemProxy(item, indices_so_far)
                if array_metadata is not None:
                    proxy.__dict__["array_metadata"] = array_metadata
                if axis_link_explicit is not None:
                    # Explicit list: pick by position-in-selection so
                    # subset slices (array: 1..2) and non-contiguous
                    # ones (array: 1,3,5) both index correctly. With no
                    # subset, this equals (idx - outer_low).
                    proxy.__dict__["axis_link_override"] = (
                        axis_link_explicit[outer_position[indices_so_far[0]]]
                    )
                elif axis_link_template is not None:
                    # Implicit '%d': substitute the outermost index into
                    # the template.
                    try:
                        substituted = axis_link_template % indices_so_far[0]
                    except (TypeError, ValueError) as ex:
                        raise ValueError(
                            f"Invalid axis-link format string "
                            f"{axis_link_template!r} for array element "
                            f"{indices_so_far[0]} of {item.name!r}: {ex}"
                        )
                    proxy.__dict__["axis_link_override"] = substituted

                yield proxy, idx_config
                return

            (low, high), *rest = remaining_dims
            depth = len(indices_so_far)

            # Per-dim selector: empty string means "iterate full bounds".
            selector = per_dim_selectors[depth] if depth < len(per_dim_selectors) else ""

            for idx in parse_array_settings(selector, (low, high)):
                if depth == 0 and names is not None:
                    # Position-in-selection indexing so subset and
                    # non-contiguous slices map names correctly. With
                    # no subset, outer_position[idx] == idx - low.
                    suffix = ":" + names[outer_position[idx]]
                elif depth == 0:
                    expand_digits = index_digits(high)
                    suffix = get_array_suffix(
                        config, idx, default=f":%.{expand_digits}d"
                    )
                else:
                    # Inner dimension: numeric default only, no expand: or
                    # expand-names overrides for nested levels.
                    expand_digits = index_digits(high)
                    suffix = (f":%.{expand_digits}d") % idx

                yield from expand(rest, indices_so_far + (idx,),
                                  pv_so_far + suffix)

        yield from expand(dimensions, (), config["pv"])

    def get_all_options(subitems, handler, pragmas):
        split_pragma = split_pytmc_pragma("\n".join(pragmas))
        for pvname, separated_cfg in separate_configs_by_pv(split_pragma):
            config = dictify_config(separated_cfg)

            # config will have the SUBITEM key, applicable to its level
            # in the hierarchy. If it exists, merge it with our current set.
            if SUBITEM in config:
                _merge_subitems(subitems, config[SUBITEM])

            for key, value in subitems.get(PRAGMA, []):
                config[key] = value

            yield from handler(item, pvname, config)

    def _pragmas_request_expansion(pragma_texts):
        """
        True iff any pragma block in *pragma_texts* contains an ``expand:``
        or ``expand-names:`` key.

        Used to route primitive arrays (``ARRAY OF BOOL/INT/REAL/...``)
        through the element-wise expansion path when the user has
        explicitly asked for per-element records. Without this opt-in,
        primitive arrays continue to produce a single waveform record
        (the existing default behavior).

        Parses each pragma block with ``split_pytmc_pragma`` and looks
        for an entry whose ``title`` is ``expand`` or ``expand-names``.
        Parsing (rather than substring matching) avoids false positives
        from values that happen to contain the literal text ``expand``
        (e.g. a ``pv:`` value).
        """
        for text in pragma_texts:
            if text is None:
                continue
            try:
                for line in split_pytmc_pragma(text):
                    if line.get("title") in ("expand", "expand-names"):
                        return True
            except ValueError:
                # A malformed pragma will surface from the main parse
                # path with a useful error message; don't shadow it here.
                continue
        return False

    # `subitems` keeps track of forward references with pragmas of members
    # and sub-members (and so on)
    subitems = {}

    for item in chain:
        subitems = subitems.get(item.name, {})
        pragmas = list(
            pragma for pragma in parser.get_pragma(item, name=pragma) if pragma is not None
        )
        if not pragmas:
            if allow_no_pragma:
                pragmas = [None]
                yield [(item, None)]
                continue

            # If any pragma in the chain is unset, escape early
            return []

        if item.array_info and (
            item.data_type.is_complex_type
            or item.data_type.is_enum
            or item.data_type.is_string
            # Primitive arrays (BOOL/INT/REAL/...) opt into element-wise
            # expansion via ``expand:`` or ``expand-names:``. Without the
            # opt-in they continue to fall through to ``handle_scalar``,
            # which produces a single waveform record (the legacy default).
            or _pragmas_request_expansion(pragmas)
        ):
            options = get_all_options(subitems, handle_array_complex, pragmas)
        else:
            options = get_all_options(subitems, handle_scalar, pragmas)

        yield list(options)


def expand_configurations_from_chain(
    chain, *, pragma: str = "pytmc", allow_no_pragma=False
):
    """
    Generate all possible configuration combinations

    For example, from a chain with two items::

        [item1, item2]

    The latter of which has a configuration that creates two PVs (specified by
    configuration dictionaries config1, config2), this function will return::

        [
            [(item1, config1), (item2, config1)],
            [(item1, config1), (item2, config2)],
        ]

    Special handling for arrays of complex types will unroll the array into
    individual elements.  That is, `arr : ARRAY [1..5] of ST_Structure` will be
    unrolled into `arr[1]` through `arr[5]`.

    Returns
    -------
    tuple
        Tuple of tuples. See description above.
    """
    result = _expand_configurations_from_chain(
        chain, pragma=pragma, allow_no_pragma=allow_no_pragma
    )
    if not result:
        return []

    return list(itertools.product(*result))


def squash_configs(*configs):
    """
    Take a list of configurations, and squash them into one dictionary

    The key 'pv' will be a list of all PV segments found.

    Later configurations override prior ones.

    Parameters
    ----------
    *configs : list of dict
        Configurations to squash. Original configs will not be modified.
    """
    squashed = {"pv": [], "field": {}}

    has_link = any("link" in config for config in configs if config is not None)
    if has_link:
        squashed["link"] = []

    for config in configs:
        if config is None:
            squashed["pv"].append(None)
            continue
        # Shallow copy so that we don't modify the original
        config = dict(config)

        # Remove the PV portion - as it should be listified
        squashed["pv"].append(config.pop("pv", None))

        if has_link:
            squashed["link"].append(config.pop("link", None))

        # Update the fields as a dictionary
        fields = config.pop("field", None)
        if fields:
            squashed["field"].update(fields)

        squashed.update(config)

    return squashed


def normalize_io(io):
    """
    Normalize an 'io' specifier in a pragma into either 'input' or 'output'

    Parameters
    ----------
    io : str
        The I/O specifier from the pragma

    Returns
    -------
    {'input', 'output'}

    Raises
    ------
    ValueError
        If an invalid specifier is given
    """
    if io in IO_OUTPUT:
        return "output"
    if io in IO_INPUT:
        return "input"
    raise ValueError("Invalid I/O specifier")


def _parse_rate(rate, hz_or_sec):
    """
    Parse rate into frequency and seconds

    Parameters
    ----------
    rate : str
        The pragma-specified rate.

    hz_or_sec : str
        {'hz', 's'}

    Returns
    -------
    dict
        With keys {'seconds', 'frequency'}
    """

    try:
        rate = float(rate)
    except Exception:
        raise ValueError(f"Invalid rate: {rate}")

    if hz_or_sec == "hz":
        freq, seconds = rate, 1.0 / rate
    elif hz_or_sec == "s":
        freq, seconds = 1.0 / rate, rate
    else:
        raise ValueError(f"Invalid hz_or_sec: {hz_or_sec}")

    return dict(
        frequency=int(freq) if int(freq) == freq else freq,
        seconds=int(seconds) if int(seconds) == seconds else seconds,
    )


def parse_update_rate(update, default=UPDATE_RATE_DEFAULT):
    """
    Parse an 'update' specifier in a pragma

    Parameters
    ----------
    update : str
        The update rate specifier from the pragma.

    Returns
    -------
    dict
        With keys {'seconds', 'frequency', 'method'}
        Where 'method' is one of: {'poll', 'notify'}

    Raises
    ------
    ValueError
        If an invalid pragma is supplied
    """
    update = update.lower().strip()
    res = dict(default)
    if update:
        match = _UPDATE_RE.match(update)
        if not match:
            raise ValueError(f"Invalid update specifier: {update}")

        # Method
        d = match.groupdict()
        method = d.get("method") or default["method"]
        if method not in {"poll", "notify"}:
            raise ValueError(f"Invalid update method: {method}")
        res["method"] = method

        # Rate + frequency/seconds
        res.update(_parse_rate(d["rate"], d["hz_or_sec"]))

        if method == "poll" and res["frequency"] not in VALID_POLL_RATES_HZ:
            raise ValueError(
                f"Invalid poll rate {res['frequency']}.  "
                f"Valid frequencies in Hz are: {VALID_POLL_RATES_HZ}"
            )

    return res


def parse_archive_settings(archive, default=ARCHIVE_DEFAULT):
    """
    Parse an 'archive' specifier in a pragma

    Parameters
    ----------
    archive : str
        The archive specifier from the pragma.

    Returns
    -------
    dict
        With keys {'seconds', 'frequency', 'method'}
        Where 'method' is one of: {'scan', 'monitor'}

    Raises
    ------
    ValueError
        If an invalid pragma is supplied
    """
    archive = archive.lower().strip()
    if archive in ("no",):
        return None

    res = dict(default)
    if archive:
        match = _ARCHIVE_RE.match(archive)
        if not match:
            raise ValueError(f"Invalid archive specifier: {archive}")

        # Method
        d = match.groupdict()
        method = d.get("method") or default["method"]
        if method not in {"scan", "monitor"}:
            raise ValueError(f"Invalid archive method: {method}")

        res["method"] = method
        # Rate + frequency/seconds
        res.update(_parse_rate(d["rate"], d["hz_or_sec"]))

    return res


def parse_array_settings(pragma, dimensions):
    """
    Parse an 'array' specifier in a pragma, yielding array elements.

    Parameters
    ----------
    pragma : str
        The I/O specifier from the pragma.

    dimensions : 2-tuple
        Lower and upper-bound of the array corresponding to the pragma.

    Yields
    ------
    element : int
        Integer element of selected array indices.

    Raises
    ------
    ValueError
        If an invalid pragma is supplied
    """
    pragma = pragma.strip()

    try:
        low, high = dimensions
    except Exception:
        raise ValueError(
            f"Invalid dimensions {dimensions!r} for array specifier in pragma "
            f"{pragma!r}"
        )

    if not pragma:
        yield from range(low, high + 1)
        return

    def _parse_element(elem):
        if ".." not in elem:
            return [int(elem)]

        # Split by .., such that this will support:
        #   ..to, from.., from..to, from..to..step
        range_args = [int(idx) if idx else None for idx in elem.split("..")]

        # Ensure we have start, stop, step
        range_args += [None] * (3 - len(range_args))
        elem_low, elem_high, elem_step = range_args

        elem_low = low if elem_low is None else elem_low
        # Add one to make the exclusive upper bound inclusive:
        elem_high = high + 1 if elem_high is None else elem_high + 1
        elem_step = 1 if elem_step is None else elem_step
        return range(elem_low, elem_high, elem_step)

    try:
        for elem in pragma.split(","):
            for idx in _parse_element(elem):
                if not low <= idx <= high:
                    raise ValueError(
                        f"Array pragma index out of bounds: " f"{low} < {elem} < {high}"
                    )
                yield idx
    except Exception as ex:
        raise ValueError(f"Invalid array pragma: {pragma} ({ex})")


# Helpers which normalize various pragma values.
_normalizers = {
    "io": (normalize_io, "io"),
    "update": (parse_update_rate, "1s poll"),
    "archive": (parse_archive_settings, "1s scan"),
}


def normalize_config(config):
    """
    Parse and normalize pragma values into Python representations

    The following keys will be interpreted: ``io``, ``archive``, ``update``

    Parameters
    ----------
    config : dict
        The configuration

    Returns
    -------
    dict
        A shallow-copy of ``config`` with parsed and normalized values
    """
    ret = dict(config)
    for key, (parser_func, default) in _normalizers.items():
        ret[key] = parser_func(ret.get(key, default))
    return ret


class SingularChain:
    """
    A chain of data types, all with pytmc pragmas, representing a single piece
    of data that should be accessible via EPICS/ADS

    Parameters
    ----------
    item_to_config : dict
        Keys would be ``TwincatItem`` s such as Symbol, and values would be
        dictionary configurations from parsed pytmc pragmas.

    Attributes
    ----------
    item_to_config : dict
    chain : list
        The chain of items (i.e., item_to_config keys)
    tcname : str
        The full TwinCAT name of the item
    pvname : str
        The user-specified PV name
    last : list
        The last item, which determines the overall data type
    data_type : DataType
        The data type of the last item
    config : dict
        The final configuration based on the full chain of configurations
    """

    def __init__(self, item_to_config):
        self.item_to_config = item_to_config
        self.chain = list(self.item_to_config)
        self.last = self.chain[-1]
        self.data_type = self.chain[-1].data_type
        self.array_info = self.chain[-1].array_info
        self.tcname = ".".join(part.name for part in self.chain)

        self.valid = True

        for config in item_to_config:
            # Detect Nones signifying an incomplete pragma
            if item_to_config[config] is None:
                self.valid = False

        self.config = squash_configs(*list(item_to_config.values()))
        self.pvname = ":".join(
            pv_segment for pv_segment in self.config["pv"] if pv_segment
        )

    def __repr__(self):
        return (
            f"<{self.__class__.__name__} pvname={self.pvname!r} "
            f"tcname={self.tcname!r} config={self.config} "
            f"data_type={self.data_type!r})"
        )


def find_pytmc_symbols(tmc, allow_no_pragma=False):
    "Find all symbols in a tmc file that contain pragmas"
    for symbol in tmc.find(parser.Symbol):
        if parser.has_pragma(symbol) or allow_no_pragma:
            if symbol.name.count(".") == 1:
                yield symbol


def always_true(*a, **kwargs):
    return True


def chains_from_symbol(symbol, *, pragma: str = "pytmc", allow_no_pragma=False):
    "Build all SingularChain instances from a Symbol"
    if allow_no_pragma:
        condition = always_true
    else:
        condition = parser.has_pragma
    for full_chain in symbol.walk(condition=condition):
        configs = itertools.product(
            *_expand_configurations_from_chain(
                full_chain, allow_no_pragma=allow_no_pragma
            )
        )
        for item_and_config in configs:
            yield SingularChain(dict(item_and_config))


def _metadata_packages_from_chain(ads_port, chain, seen):
    """
    Yield a StPositionStateRecordPackage for each state table in the chain that has
    not been seen yet (``seen`` is updated). A state table that lacks
    ``array:`` or ``expand-names:`` raises ValueError, once per table.
    """
    pv_segments = []
    tcnames = []
    for item, config in chain.item_to_config.items():
        metadata = getattr(item, "array_metadata", None)
        if metadata is None:
            tcnames.append(item.name)
            pv_segments.append(config.get("pv") if config else None)
            continue

        base_item = item.__dict__["item"]
        segments = pv_segments + [metadata["pv"]]
        tcname = ".".join(tcnames + [base_item.name])
        key = (ads_port, tcname)
        if key in seen:
            return
        seen.add(key)
        if metadata["missing"]:
            raise ValueError(
                f"{base_item.name!r} is a state table (2D array of "
                f"{STATE_TABLE_TYPE}) and with the FB_MotionStage motion library "
                f"requires both 'array:' and 'expand-names:' in its pragma; "
                f"missing: {', '.join(metadata['missing'])}"
            )
        yield StPositionStateRecordPackage(
            ads_port,
            chain,
            metadata,
            tcname=tcname,
            pv_segments=segments,
        )
        return


def record_packages_from_symbol(
    symbol,
    *,
    pragma: str = "pytmc",
    yield_exceptions=False,
    allow_no_pragma=False,
    state_table_metadata=False,
):
    """
    Create all record packages from a given Symbol.

    With ``state_table_metadata`` each state table (2D array of
    ST_PositionState) also yields its metadata records, and one that lacks
    ``array:`` or ``expand-names:`` is an error. :func:`pytmc.bin.db.process`
    sets it for a project that uses the new motion library (see
    :func:`pytmc.motion_library.uses_new_library`).
    """
    try:
        ads_port = symbol.module.ads_port
        seen_metadata = set()
        for chain in chains_from_symbol(
            symbol, pragma=pragma, allow_no_pragma=allow_no_pragma
        ):
            try:
                yield RecordPackage.from_chain(ads_port, chain=chain)
                if state_table_metadata:
                    yield from _metadata_packages_from_chain(
                        ads_port, chain, seen_metadata
                    )
            except Exception as ex:
                if yield_exceptions:
                    yield type(ex)(
                        f"Symbol {symbol.name} " f"chain: {chain.tcname}: {ex}"
                    )
                else:
                    raise
    except Exception as ex:
        if yield_exceptions:
            yield type(ex)(f"Symbol {symbol.name} failure: {ex}")
        else:
            raise


def _attach_pragma(item, name, value):
    """Attach a pragma to a TwincatItem using `_make_fake_item`."""
    if not hasattr(item, "Properties"):
        properties = parser._make_fake_item("Properties", parent=item)
        properties.Property = []
        item.Properties = [properties]

    properties = item.Properties[0]
    prop = parser._make_fake_item(
        "Property", parent=properties, text=value, item_name=name
    )
    properties.Property.append(prop)
    return prop


class _FakeSymbol(parser.Symbol):
    @property
    def data_type(self):
        return self._data_type

    @property
    def qualified_type_name(self):
        return self._data_type.qualified_type

    @property
    def type_name(self):
        return self._data_type.name

    @property
    def BitSize(self):
        return self._data_type.BitSize


def make_fake_symbol_from_data_type(
    data_type,
    symbol_pragma_text,
    *,
    name="$(SYMBOL)",
    pragma_name: str = "pytmc",
    data_area_index=0,
    tmc=None,
    create_data_area_if_needed=True,
):
    """
    Create a :class:`_FakeSymbol` from the given data type.

    Parameters
    ----------
    data_type : pytmc.parser.DataType
        The TMC data type.

    symbol_pragma_text : str
        The pragma text to attach.

    name : str, optional
        The symbol name.

    pragma_name : str, optional
        The pragma name to use (defaults to "pytmc").

    data_area_index : int, optional
        The data area to pretend the symbol exists in.
    """
    if tmc is None:
        # If defined in a .tmc file, this is the obvious choice.
        tmc = data_type.tmc
        if tmc is None:
            # Fallback to the first .tmc we find.  This really should be an
            # error condition, but given that we're making fake symbols anyway
            # it _probably_ doesn't matter.
            project = data_type.find_ancestor(parser.TcSmProject)
            for plc in project.plcs:
                tmc = plc.tmc
                if tmc is not None:
                    break

    if tmc is None:
        raise ValueError("Unable to find a tmc to insert the symbol")

    # TODO: does data area make a difference?
    data_areas = list(tmc.find(parser.DataArea))
    if not data_areas:
        if not create_data_area_if_needed:
            raise ValueError("No data area found to create symbol")
        data_area = tmc.create_data_area()
    else:
        data_area = data_areas[data_area_index]

    sym = parser._make_fake_item("_FakeSymbol", parent=data_area, item_name=name)
    sym._data_type = data_type
    sym.BitOffs = parser._make_fake_item("BitOffs", parent=sym, text="0")
    _attach_pragma(sym, pragma_name, symbol_pragma_text)
    return sym
